local function beast(ctx,e)for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if tag=="beast"or tag=="all"then return true end end return false end
return {api_version=1,id="CS2_237",name="Starving Buzzard",text="Whenever you summon a Beast, draw a card.",set="LEGACY",type="minion",class="hunter",cost=2,attack=2,health=1,tags={"beast"},triggers={{event="minion_summoned",timing="after",active_zones={"board"},condition=function(ctx,self,e)return e.player==ctx:controller(self)and beast(ctx,e.entity)end,effect=function(ctx,self)ctx:draw(ctx:controller(self),1)end}}}
